def solve(n):
    """Return the number of prime numbers strictly less than n.
    Uses a simple Sieve of Eratosthenes. Handles n <= 2 by returning 0.
    """
    if n <= 2:
        return 0
    limit = n - 1  # highest number to consider
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
