def solve(matrix):
    # Determinant of a square integer matrix.
    # Empty matrix (0x0) has determinant 1 by definition.
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square
    for row in matrix:
        if len(row) != n:
            raise ValueError('non-square matrix')
    # Use Fraction for exact arithmetic
    from fractions import Fraction
    a = [[Fraction(x) for x in row] for row in matrix]
    det = Fraction(1)
    sign = 1
    for i in range(n):
        # Find pivot
        pivot = None
        for r in range(i, n):
            if a[r][i] != 0:
                pivot = r
                break
        if pivot is None:
            return 0
        if pivot != i:
            # swap rows
            a[i], a[pivot] = a[pivot], a[i]
            sign *= -1
        piv_val = a[i][i]
        det *= piv_val
        # Normalize row i
        for c in range(i, n):
            a[i][c] /= piv_val
        # Eliminate below
        for r in range(i+1, n):
            factor = a[r][i]
            if factor == 0:
                continue
            for c in range(i, n):
                a[r][c] -= factor * a[i][c]
    # determinant is sign * product of pivots (det already multiplied by pivots)
    det = det * sign
    # det should be integer
    return int(det)

def solve(a):
    a = list(a)
    n = len(a)
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i >= 0:
        j = n - 1
        while a[j] <= a[i]:
            j -= 1
        a[i], a[j] = a[j], a[i]
    a[i + 1:] = a[i + 1:][::-1]
    return a

