def solve(*args):
    if len(args) == 1:
        items = args[0] if isinstance(args[0], (list, tuple)) else [args[0]]
    else:
        items = list(args)
    out = []
    seen = set()
    stack = list(reversed(list(items)))
    while stack:
        item = stack.pop()
        if isinstance(item, (list, tuple)):
            i = id(item)
            if i in seen:
                continue
            seen.add(i)
            stack.extend(reversed(list(item)))
        else:
            out.append(item)
    return out

