def solve(path):
    """Simplify an absolute Unix path.
    Args:
        path (str): absolute Unix path starting with '/'.
    Returns:
        str: canonical simplified path.
    """
    # Split path by '/', ignore empty and '.' components.
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack empty, remain at root.
        else:
            stack.append(part)
    # Reassemble with leading slash. Root is '/' when stack empty.
    return '/' + '/'.join(stack)

