def solve(matrix):
    # Determinant of a square integer matrix.
    # Empty matrix (0x0) has determinant 1 by definition.
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square
    for row in matrix:
        if len(row) != n:
            raise ValueError('non-square matrix')
    # Use Gaussian elimination with fractions for exact integer result
    from fractions import Fraction
    a = [[Fraction(x) for x in row] for row in matrix]
    sign = 1
    det = Fraction(1)
    for i in range(n):
        # Find pivot row
        pivot = i
        while pivot < n and a[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            sign *= -1
        piv = a[i][i]
        det *= piv
        # Normalize pivot row
        for col in range(i, n):
            a[i][col] /= piv
        # Eliminate below
        for row in range(i+1, n):
            factor = a[row][i]
            if factor == 0:
                continue
            for col in range(i, n):
                a[row][col] -= factor * a[i][col]
    return int(det * sign)

