{"task_id": "T25", "code": "def solve(matrix):
    # Bareiss algorithm for exact integer determinant
    if not matrix:
        return 1
    n = len(matrix)
    # ensure square
    for row in matrix:
        if len(row) != n:
            raise ValueError('non-square matrix')
    # make copy as integers
    a = [list(map(int, row)) for row in matrix]
    sign = 1
    det_prev = 1  # denominator for Bareiss (det of previous pivot)
    for k in range(n-1):
        # pivot selection
        if a[k][k] == 0:
            # find non-zero pivot below
            swap_row = None
            for i in range(k+1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            a[k], a[swap_row] = a[swap_row], a[k]
            sign = -sign
        pivot = a[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Compute new element using integer arithmetic
                a[i][j] = (a[i][j]*pivot - a[i][k]*a[k][j]) // det_prev
            a[i][k] = 0
        det_prev = pivot
    # After elimination, last element is determinant
    return sign * a[n-1][n-1]
