def solve(meetings):
    # meetings: list of [start, end] intervals. Return max non-overlapping count.
    if not meetings:
        return 0
    # Ensure each meeting is a sequence of length 2
    intervals = []
    for m in meetings:
        # Convert to list to avoid tuple issues
        try:
            s, e = m[0], m[1]
        except Exception:
            # Invalid format, skip
            continue
        intervals.append((s, e))
    # Sort by end time, then start
    intervals.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for s, e in intervals:
        if s >= current_end:
            count += 1
            current_end = e
    return count

