        return 0
    intervals = []
    for m in meetings:
        if not isinstance(m, (list, tuple)):
            continue
        if len(m) < 2:
            continue
        s, e = m[0], m[1]
        # ensure comparable
        try:
            if s > e:
                continue
        except Exception:
            continue
        intervals.append((s, e))
    # sort by end then start
    intervals.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for s, e in intervals:
        if s >= current_end:
            count += 1
            current_end = e
    return count

