def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Implements the patience sorting algorithm with O(n log n) complexity.
    """
    import bisect
    if not nums:
        return 0
    tails = []
    for x in nums:
        # Find insertion point (first element >= x)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

