    """Count islands in a possibly irregular grid.
    grid is a list of lists where each inner list may have different length.
    Cells with value 1 are land; adjacency is up/down/left/right respecting row lengths.
    """
    if not grid:
        return 0
    visited = set()
    count = 0
    rows = len(grid)
    for i in range(rows):
        cols = len(grid[i])
        for j in range(cols):
            if grid[i][j] == 1 and (i, j) not in visited:
                count += 1
                # DFS
                stack = [(i, j)]
                visited.add((i, j))
                while stack:
                    x, y = stack.pop()
                    # four directions
