def solve(a, x):
    """Return the leftmost index at which ``x`` could be inserted into sorted sequence ``a``.
    ``a`` can be any iterable (list, tuple, etc.). If ``a`` is not iterable, treat it as empty.
    """
    try:
        seq = list(a)
    except Exception:
        seq = []
    lo, hi = 0, len(seq)
    while lo < hi:
        mid = (lo + hi) // 2
        if seq[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

