def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Supports binary operators '+', '-', '*', '/' where division truncates toward zero.
    Tokens are strings; numbers may be negative.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division
                # Truncate toward zero as required
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

