def solve(n, edges):
    import heapq
    if n == 0:
        return -1
    # build adjacency list
    adj = [[] for _ in range(n)]
    for a,b,w in edges:
        adj[a].append((b,w))
        adj[b].append((a,w))
    # Dijkstra from 0 to n-1
    INF = 10**18
    dist = [INF]*n
    dist[0] = 0
    pq = [(0,0)]
    while pq:
        d,u = heapq.heappop(pq)
        if d!=dist[u]:
            continue
        if u == n-1:
            break
        for v,w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq,(nd,v))
    if n==1:
        return 0
    return dist[n-1] if dist[n-1]!=INF else -1

